trend.option.xAxis.data.push (timeText);
trend.option.series[0].data.push(tags.EXHAUTS_TT_PV.val);
trend.option.series[1].data.push(tags.PRODUCT_TT_PV.val);
trend.option.series[2].data.push(tags.GAS_PDT_PV.val);
if (trend.option.xAxis.data.length > 600) {
    trend.option.xAxis.data.shift();
}
trend.option.series.forEach(series => {
    if (series.data.length > 600) {
        series.data.shift();
    }
});
msg.payload = {maintrend : trend};

if (!trend.hisbuf) trend.hisbuf = [];
for (let tagname in tagscfg){
    trend.hisbuf.push({
        tagname,
        value: tags[tagname].val,
        ts: now  
    });

}

return msg;

