CREATE TABLE IF NOT EXISTS his (
    time        timestamptz NOT NULL,
    tagname     text NOT NULL,
    value       double precision,
    batch_id    integer
);

-- індекси
CREATE INDEX IF NOT EXISTS idx_his_time 
    ON his (time);

CREATE INDEX IF NOT EXISTS idx_his_tagname 
    ON his (tagname);

CREATE INDEX IF NOT EXISTS idx_his_batch_id 
    ON his (batch_id);

-- комбінований (часто найкорисніший)
CREATE INDEX IF NOT EXISTS idx_his_tag_time 
    ON his (tagname, time);

