// ініціалізація
const trend = global.get("trends.maintrend");
// перевірка часу
let buf = trend.hisbuf;
const now = new Date();

if (buf.length > 0) {
    let firstTs = new Date (buf[0].ts);
    let diff = now.valueOf() - firstTs.valueOf();

    if (diff >= 5000) {
        // формуємо VALUES
        let values = buf.map(r => {
            let t = new Date(r.ts).toISOString();
            let v = (r.value !== null && r.value !== undefined) ? r.value : 'NULL';
            return `('${t}', '${r.tagname}', ${v}, NULL)`;
        }).join(',');

        let sql = `
            INSERT INTO his (time, tagname, value, batch_id)
            VALUES ${values};
        `;
        // очистка буфера
        trend.hisbuf = [];
        msg.query = sql;
        return msg;
    }
}
